//! The synthetic fixtures under `testdata/golden/<format>/` (generated by
//! `testdata/synth/formatos_financeiros.py`) parse into the expected tables, items and
//! warnings through the same dispatcher a run uses.

use std::path::PathBuf;

use chrono::NaiveDate;
use dm_core::{ColumnRole, ItemKind, Locator, Money, Table, Value};
use dm_ingest::{parse_bytes, InboxContext, ParsedSource, SourceKind};

fn golden(path: &str) -> PathBuf {
    PathBuf::from(
        std::env::var("CARGO_MANIFEST_DIR")
            .expect("cargo define CARGO_MANIFEST_DIR ao rodar os testes"),
    )
    .join("../../../../testdata/golden")
    .join(path)
}

fn parse(path: &str) -> ParsedSource {
    let file = golden(path);
    let bytes = std::fs::read(&file).unwrap_or_else(|e| panic!("{}: {e}", file.display()));
    let name = file
        .file_name()
        .and_then(|n| n.to_str())
        .unwrap_or_default()
        .to_string();
    parse_bytes(&name, &bytes, &InboxContext::default()).unwrap_or_else(|e| panic!("{e}"))
}

fn cell<'a>(t: &'a Table, row: usize, col: &str) -> &'a Value {
    let c = t
        .column_index(col)
        .unwrap_or_else(|| panic!("{}: sem coluna {col}", t.name));
    t.value(row, c)
        .unwrap_or_else(|| panic!("{}: sem linha {row}", t.name))
}

fn text<'a>(t: &'a Table, row: usize, col: &str) -> Option<&'a str> {
    cell(t, row, col).as_text()
}

fn money(t: &Table, row: usize, col: &str) -> Option<i64> {
    cell(t, row, col).as_money().map(Money::centavos)
}

fn date(y: i32, m: u32, d: u32) -> Option<NaiveDate> {
    NaiveDate::from_ymd_opt(y, m, d)
}

#[test]
fn pdf_statement_with_credit_and_debit_columns() {
    let src = parse("pdf/extrato_credito_debito.pdf");
    assert_eq!(src.sniff.kind, SourceKind::Pdf);
    assert_eq!(src.tables.len(), 1);
    let t = &src.tables[0];
    assert_eq!(t.len(), 7);
    let rows: Vec<(Option<NaiveDate>, &str, Option<&str>, i64)> = (0..t.len())
        .map(|r| {
            (
                cell(t, r, "data").as_date(),
                text(t, r, "historico").unwrap_or_default(),
                text(t, r, "documento"),
                money(t, r, "valor").unwrap_or_default(),
            )
        })
        .collect();
    assert_eq!(
        rows,
        vec![
            (
                date(2026, 7, 1),
                "PIX RECEBIDO PADARIA CENTRAL LTDA",
                None,
                150_000
            ),
            (date(2026, 7, 1), "TARIFA MENSALIDADE PACOTE", None, -4_590),
            (
                date(2026, 7, 3),
                "LIQUIDACAO COBRANCA",
                Some("123456"),
                234_010
            ),
            (
                date(2026, 7, 3),
                "PAGAMENTO BOLETO ENERGIA",
                Some("778899"),
                -89_000
            ),
            (
                date(2026, 7, 4),
                "TED RECEBIDA 45723174000110",
                None,
                1_000_000
            ),
            (
                date(2026, 7, 8),
                "DEBITO AUTOMATICO SEGURO",
                Some("4455"),
                -21_033
            ),
            (date(2026, 7, 9), "PIX RECEBIDO MARIA DA SILVA", None, 7_500),
        ]
    );
    assert_eq!(money(t, 6, "saldo"), Some(1_776_887));
    assert_eq!(text(t, 1, "tipo"), Some("D"));
    assert_eq!(cell(t, 5, "pagina"), &Value::Integer(2));
    // Headers, the opening balance and the footers stay as page items.
    assert!(src.items.iter().all(|i| i.kind == ItemKind::PageRegion));
    assert!(src.items.iter().any(|i| i
        .text()
        .is_some_and(|x| x.contains("SALDO ANTERIOR 5.000,00"))));
    // The third page is only an image.
    assert_eq!(src.warnings.len(), 1, "{:?}", src.warnings);
    assert!(src.warnings[0].contains("página(s) sem texto"));
    assert!(src.warnings[0].contains(": 3;"));
}

#[test]
fn scanned_pdf_says_ocr_is_not_available() {
    let src = parse("pdf/extrato_digitalizado.pdf");
    assert!(src.tables.is_empty());
    assert!(src.items.is_empty());
    assert_eq!(
        src.warnings,
        vec!["extrato_digitalizado.pdf: PDF sem camada de texto (digitalizado ou só imagens): o OCR ainda não está disponível, nenhum conteúdo foi lido".to_string()]
    );
}

#[test]
fn pdf_letter_becomes_page_items_with_boxes_and_mentions() {
    let src = parse("pdf/carta_cobranca.pdf");
    assert!(src.tables.is_empty(), "one dated amount is not a statement");
    assert!(src.warnings.is_empty(), "{:?}", src.warnings);
    assert_eq!(src.items.len(), 4);
    let first = &src.items[0];
    let Locator::Page { page, bbox } = &first.locator else {
        panic!("{:?}", first.locator);
    };
    assert_eq!(*page, 1);
    assert!(bbox[0] < bbox[2] && bbox[1] < bbox[3], "{bbox:?}");
    assert!(bbox.iter().all(|v| (0.0..=1.0).contains(v)), "{bbox:?}");
    assert!(bbox[1] < 0.1, "origin is the top of the page: {bbox:?}");
    assert!(first
        .entity_mentions
        .iter()
        .any(|m| m.normalized.as_deref() == Some("11222333000181")));
    assert!(src
        .items
        .iter()
        .any(|i| i.text() == Some("05/07/2026 Parcela única 17.380,00")));
}

#[test]
fn cnab240_collection_return_every_movement() {
    let src = parse("cnab240/retorno_cobranca.ret");
    assert_eq!(src.sniff.kind, SourceKind::Cnab240);
    assert!(src.warnings.is_empty(), "{:?}", src.warnings);
    let t = &src.tables[0];
    assert!(dm_ingest::cnab::is_collection_table(t));
    let situations: Vec<&str> = (0..t.len())
        .map(|r| text(t, r, "situacao").unwrap_or_default())
        .collect();
    assert_eq!(
        situations,
        vec!["Aberto", "Liquidado", "Baixado", "Rejeitado", "Tarifa"]
    );
    assert_eq!(money(t, 1, "valor_do_titulo"), Some(234_010));
    assert_eq!(money(t, 1, "valor_pago"), Some(239_000));
    assert_eq!(money(t, 1, "juros_e_multa"), Some(4_990));
    assert_eq!(money(t, 1, "tarifa"), Some(210));
    assert_eq!(money(t, 1, "valor_liquido"), Some(238_790));
    assert_eq!(cell(t, 1, "data_do_credito").as_date(), date(2026, 7, 13));
    assert_eq!(text(t, 2, "inscricao_do_sacado"), Some("12345678909"));
    assert_eq!(text(t, 3, "motivo"), Some("0809"));
}

#[test]
fn cnab240_remittance_and_payments() {
    let rem = parse("cnab240/remessa_cobranca.rem");
    let t = &rem.tables[0];
    assert_eq!(t.len(), 2);
    assert_eq!(text(t, 0, "especie"), Some("Duplicata de serviço"));
    assert_eq!(text(t, 1, "especie"), Some("Duplicata mercantil"));
    assert_eq!(cell(t, 0, "emissao").as_date(), date(2026, 7, 7));
    assert_eq!(text(t, 0, "sacado"), Some("PADARIA CENTRAL LTDA"));
    let pay = parse("cnab240/retorno_pagamentos.ret");
    let t = &pay.tables[0];
    assert!(!dm_ingest::cnab::is_collection_table(t));
    assert_eq!(t.len(), 2);
    assert_eq!(text(t, 0, "favorecido"), Some("CAIXAS BOA VISTA LTDA"));
    assert_eq!(
        text(t, 0, "inscricao_do_favorecido"),
        Some("11222333000181")
    );
    assert_eq!(money(t, 0, "valor_do_pagamento"), Some(1_470_000));
    assert_eq!(text(t, 0, "situacao"), Some("Efetivado"));
    assert_eq!(
        text(t, 1, "inscricao_do_favorecido"),
        Some("45723174000110")
    );
    assert_eq!(text(t, 1, "situacao"), Some("Agendado"));
    assert_eq!(pay.warnings.len(), 1, "{:?}", pay.warnings);
    assert!(pay.warnings[0].contains("'O'"));
}

#[test]
fn cnab400_per_bank_layouts() {
    let itau = parse("cnab400/retorno_itau_341.ret");
    assert_eq!(itau.sniff.kind, SourceKind::Cnab400);
    assert!(itau.warnings.is_empty(), "{:?}", itau.warnings);
    let t = &itau.tables[0];
    assert_eq!(text(t, 0, "nosso_numero"), Some("98765001"));
    assert_eq!(text(t, 0, "sacado"), Some("PAO E ARTE PANIFICADORA LTDA"));
    assert_eq!(text(t, 0, "uso_da_empresa"), Some("PED200311"));
    assert_eq!(money(t, 0, "tarifa"), Some(190));
    assert_eq!(cell(t, 0, "data_do_credito").as_date(), date(2026, 7, 11));
    assert_eq!(text(t, 1, "situacao"), Some("Aberto"));

    let bradesco = parse("cnab400/retorno_bradesco_237.ret");
    let t = &bradesco.tables[0];
    assert_eq!(text(t, 0, "nosso_numero"), Some("000098765004"));
    assert_eq!(text(t, 0, "motivo"), Some("00"));
    assert_eq!(text(t, 1, "situacao"), Some("Tarifa"));

    let santander = parse("cnab400/retorno_santander_033.ret");
    let t = &santander.tables[0];
    assert_eq!(text(t, 0, "nosso_numero"), Some("98765005"));
    assert_eq!(cell(t, 0, "data_do_credito").as_date(), date(2026, 7, 16));

    let bb = parse("cnab400/retorno_bb_001.ret");
    let t = &bb.tables[0];
    assert_eq!(text(t, 0, "nosso_numero"), Some("12345670098765007"));
    assert_eq!(money(t, 0, "valor_pago"), Some(4_900_000));
    assert_eq!(money(t, 0, "tarifa"), Some(350));
    assert_eq!(cell(t, 0, "data_do_credito").as_date(), date(2026, 7, 17));
    assert_eq!(cell(t, 1, "nosso_numero"), &Value::Null);
    assert_eq!(bb.warnings.len(), 1, "{:?}", bb.warnings);
    assert!(bb.warnings[0].contains("convênio de 6 posições"));

    for (file, who) in [
        ("cnab400/retorno_caixa_104.ret", "Caixa"),
        ("cnab400/retorno_sicoob_756.ret", "Sicoob"),
        ("cnab400/retorno_banco_sintetico_998.ret", "banco 998"),
    ] {
        let src = parse(file);
        assert_eq!(src.warnings.len(), 1, "{file}: {:?}", src.warnings);
        assert!(src.warnings[0].contains(who), "{:?}", src.warnings);
        assert!(src.warnings[0].contains("campos comuns"));
        let t = &src.tables[0];
        assert_eq!(cell(t, 0, "nosso_numero"), &Value::Null);
        assert_eq!(text(t, 0, "seu_numero"), Some("NF 200360"));
        assert_eq!(money(t, 0, "valor_pago"), Some(2_785_000));
        assert_eq!(text(t, 0, "situacao"), Some("Liquidado"));
    }
}

#[test]
fn sped_books_one_table_per_register() {
    let efd = parse("sped/efd_icms_ipi_jul2026.txt");
    assert_eq!(efd.sniff.kind, SourceKind::Sped);
    assert!(efd.warnings.is_empty(), "{:?}", efd.warnings);
    let names: Vec<&str> = efd.tables.iter().map(|t| t.name.as_str()).collect();
    assert_eq!(
        names,
        vec![
            "efd_icms_ipi_jul2026:0000",
            "efd_icms_ipi_jul2026:0150",
            "efd_icms_ipi_jul2026:C100",
            "efd_icms_ipi_jul2026:C170",
            "efd_icms_ipi_jul2026:C190",
            "efd_icms_ipi_jul2026:E100",
            "efd_icms_ipi_jul2026:E110",
        ]
    );
    let c100 = &efd.tables[2];
    assert_eq!(text(c100, 1, "num_doc"), Some("000512"));
    assert_eq!(money(c100, 1, "vl_doc"), Some(87_000));
    assert_eq!(cell(c100, 1, "dt_e_s").as_date(), date(2026, 7, 8));
    let e110 = &efd.tables[6];
    assert_eq!(money(e110, 0, "deb_esp"), Some(0));
    let p0150 = &efd.tables[1];
    assert_eq!(text(p0150, 1, "cpf"), Some("12345678909"));
    assert_eq!(
        p0150.columns[p0150.column_index("cnpj").unwrap_or_default()].role,
        ColumnRole::TaxId
    );

    let contrib = parse("sped/efd_contribuicoes_jul2026.txt");
    assert!(contrib.warnings.is_empty(), "{:?}", contrib.warnings);
    let zero = &contrib.tables[0];
    assert!(zero.column_index("tipo_escrit").is_some());
    assert_eq!(cell(zero, 0, "dt_ini").as_date(), date(2026, 7, 1));
    let m200 = contrib
        .tables
        .iter()
        .find(|t| t.name.ends_with(":M200"))
        .unwrap_or_else(|| panic!("sem M200"));
    assert!(m200.column_index("campo_13").is_some(), "positional names");

    let ecd = parse("sped/ecd_2025.txt");
    assert!(ecd.warnings.is_empty(), "{:?}", ecd.warnings);
    let i250 = ecd
        .tables
        .iter()
        .find(|t| t.name.ends_with(":I250"))
        .unwrap_or_else(|| panic!("sem I250"));
    assert_eq!(i250.len(), 4);
    assert_eq!(cell(i250, 2, "linha_pai"), &Value::Integer(9));
    assert_eq!(
        text(i250, 0, "hist"),
        Some("RECEBIMENTO NF 088231 PADARIA CENTRAL")
    );
}

#[test]
fn zip_entries_are_sources_of_their_own() {
    let src = parse("zip/pacote_jul2026.zip");
    assert_eq!(src.sniff.kind, SourceKind::Zip);
    assert!(src.tables.is_empty());
    assert_eq!(
        src.warnings,
        vec!["pacote_jul2026.zip/vazio.txt: arquivo vazio".to_string()]
    );
    let names: Vec<&str> = src.entries.iter().map(|e| e.name.as_str()).collect();
    assert_eq!(
        names,
        vec![
            "pacote_jul2026.zip/cobranca/retorno_cobranca.ret",
            "pacote_jul2026.zip/extratos/extrato_credito_debito.pdf",
            "pacote_jul2026.zip/titulos_unidade_norte_omie_jul2026.csv",
        ]
    );
    let kinds: Vec<SourceKind> = src.entries.iter().map(|e| e.sniff.kind).collect();
    assert_eq!(
        kinds,
        vec![SourceKind::Cnab240, SourceKind::Pdf, SourceKind::Csv]
    );
    // Ids derive from the archive and the entry path; table names and items carry the path.
    let ids: std::collections::BTreeSet<&str> = src
        .entries
        .iter()
        .map(|e| e.source_id.as_str())
        .chain([src.source_id.as_str()])
        .collect();
    assert_eq!(ids.len(), 4);
    assert_eq!(src.entries[0].tables[0].name, "cobranca/retorno_cobranca");
    assert_eq!(src.entries[0].tables[0].source_id, src.entries[0].source_id);
    let pdf = &src.entries[1];
    assert_eq!(pdf.tables[0].len(), 7);
    assert!(pdf.items.iter().all(|i| {
        i.fields.get("archive_entry").and_then(Value::as_text)
            == Some("extratos/extrato_credito_debito.pdf")
    }));
    assert_eq!(src.flatten().len(), 4);
}

#[test]
fn twin_variant_inputs_parse() {
    let ret = parse("vantara-twin-pdf-cnab240/01_retorno_cobranca_jul2026.ret");
    assert!(ret.warnings.is_empty(), "{:?}", ret.warnings);
    let t = &ret.tables[0];
    assert_eq!(t.len(), 12);
    assert_eq!(text(t, 7, "seu_numero"), Some("NF 200351"));
    assert_eq!(text(t, 7, "situacao"), Some("Aberto"));
    let pdf = parse("vantara-twin-pdf-cnab240/03_extrato_bancario_jul2026.pdf");
    assert!(pdf.warnings.is_empty(), "{:?}", pdf.warnings);
    let t = &pdf.tables[0];
    assert_eq!(t.len(), 18);
    assert_eq!(
        text(t, 8, "historico"),
        Some("PAGAMENTO FORNECEDOR NF 55120")
    );
    assert_eq!(money(t, 8, "valor"), Some(-1_470_000));
    assert_eq!(text(t, 0, "documento"), Some("000098765001"));
    assert_eq!(money(t, 17, "saldo"), Some(42_527_850));
}
